'use client';

import { motion } from 'framer-motion';

interface SquareFlipProps {
  width?: number;
  height?: number;
  color?: string;
  isAnimating?: boolean;
}

export function SquareFlip({
  width = 40,
  height = 40,
  color = "currentColor",
  isAnimating = true,
}: SquareFlipProps) {
  const size = Math.min(width, height) * 0.6;
  const x = (width - size) / 2;
  const y = (height - size) / 2;

  return (
    <svg
      width={width}
      height={height}
      viewBox={`0 0 ${width} ${height}`}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-label="Loading"
      role="img"
    >
      <motion.rect
        x={x}
        y={y}
        width={size}
        height={size}
        fill={color}
        rx={2}
        animate={{
          scaleX: [1, 0, 1],
        }}
        transition={{
          duration: 1.2,
          repeat: isAnimating ? Infinity : 0,
          ease: 'easeInOut',
          times: [0, 0.5, 1],
        }}
        style={{ originX: `${width / 2}px`, originY: `${height / 2}px` }}
      />
    </svg>
  );
}
